  - method: POST
    path: /v3/transforms
    api_version: v3
  - method: POST
    path: /v3/transforms/{transformId}/preview
    api_version: v3
auth_flow: OAuth2 bearer token
required_scopes: [idn:transforms:manage, idn:transforms:read]
key_parameters: [name, type, attributes, identityId]
