  - method: POST
    path: /v3/transforms
    api_version: v3
  - method: GET
    path: /v3/transforms/{id}
    api_version: v3
  - method: POST
    path: /v3/identity-profiles/{identityProfileId}/preview
    api_version: v3
auth_flow: OAuth2 bearer token
required_scopes: [idn:transforms:manage, idn:identity-profiles:read]
key_parameters: [name, type, attributes, values, input, identityId, identityAttributeConfig, identityAttributeName, transformDefinition]
```

